#!/usr/bin/env python3
"""Compute GT for CSX-058_Q2 from local CSX-058 records."""

from __future__ import annotations

import datetime as dt
import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-058_Q2"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-058"


def load_json(rel_path: str) -> Any:
    with (PACKAGE_DIR / rel_path).open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def read_text(rel_path: str) -> str:
    return (PACKAGE_DIR / rel_path).read_text(encoding="utf-8", errors="ignore")


def nested(data: dict[str, Any], *keys: str, default: Any = None) -> Any:
    current: Any = data
    for key in keys:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current


def clean_html(text: str) -> str:
    text = re.sub(r"<script[\s\S]*?</script>", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"<style[\s\S]*?</style>", " ", text, flags=re.IGNORECASE)
    text = re.sub(r"<[^>]+>", " ", text)
    replacements = {
        "&nbsp;": " ",
        "&#039;": "'",
        "&amp;": "&",
        "&quot;": '"',
        "&#8217;": "'",
        "&#8211;": "-",
        "&#8212;": "-",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return re.sub(r"\s+", " ", text).strip()


def inclusive_days(start: str, end: str) -> int:
    return (dt.date.fromisoformat(end) - dt.date.fromisoformat(start)).days + 1


def phrase_present(text: str, *phrases: str) -> bool:
    lowered = text.lower()
    return all(phrase.lower() in lowered for phrase in phrases)


def extract_report_amounts(report: str) -> dict[str, float]:
    checks = {
        "eastern_uae_less_than_24h_mm": phrase_present(report, "250 millimeters", "less than 24 hours"),
        "dubai_airport_daily_mm": phrase_present(report, "Dubai International Airport", "119 millimeters"),
        "uae_annual_range_mm": "140 to 200 millimeters" in report,
        "airport_typical_annual_multiplier": "1.5 times its typical annual rainfall" in report,
    }
    missing = [name for name, ok in checks.items() if not ok]
    if missing:
        raise ValueError(f"Expected rainfall anchors not found: {missing}")
    return {
        "eastern_uae_less_than_24h_mm": 250.0,
        "dubai_airport_daily_mm": 119.0,
        "uae_annual_low_mm": 140.0,
        "uae_annual_high_mm": 200.0,
        "airport_typical_annual_multiplier": 1.5,
    }


def main() -> None:
    event = load_json("metadata/event.json")
    anchor = load_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_April_2024_UAE_and_Dubai_record_rainfall_flood.json"
    )
    report = clean_html(
        read_text("data/event_reports/event_reports_004_01_Locked_package_evidence_report.html.html")
    )
    era5 = load_json("data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json")
    gpm = load_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = load_json("data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json")

    start = nested(anchor, "temporal_window", "start_date")
    end = nested(anchor, "temporal_window", "end_date")
    duration_days = inclusive_days(start, end)

    report_amounts = extract_report_amounts(report)
    eastern_mm = report_amounts["eastern_uae_less_than_24h_mm"]
    airport_mm = report_amounts["dubai_airport_daily_mm"]
    annual_midpoint = (report_amounts["uae_annual_low_mm"] + report_amounts["uae_annual_high_mm"]) / 2.0
    eastern_annual_ratio = eastern_mm / annual_midpoint
    airport_annual_ratio = airport_mm / annual_midpoint
    airport_typical_annual = airport_mm / report_amounts["airport_typical_annual_multiplier"]

    gridded_precip = {
        "era5_land_event_max_mm": round(float(era5["stats"]["precipitation_sum_mm_max"]), 3),
        "gpm_event_max_mm": round(float(gpm["stats"]["gpm_event_precip_mm_max"]), 3),
        "chirps_event_max_mm": round(float(chirps["stats"]["chirps_event_precip_mm_max"]), 3),
    }
    max_gridded_precip = max(gridded_precip.values())
    airport_to_grid_ratio = airport_mm / max_gridded_precip
    eastern_to_grid_ratio = eastern_mm / max_gridded_precip

    primary_gt = {
        "duration_days": duration_days,
        "annual_midpoint_mm": round(annual_midpoint, 1),
        "eastern_annual_ratio": round(eastern_annual_ratio, 2),
        "airport_annual_ratio": round(airport_annual_ratio, 2),
        "airport_typical_annual_mm": round(airport_typical_annual, 1),
        "max_gridded_precip_mm": round(max_gridded_precip, 3),
        "report_to_grid_ratios": {
            "airport": round(airport_to_grid_ratio, 2),
            "eastern": round(eastern_to_grid_ratio, 2),
        },
        "final_label": "annual_scale_short_duration_rainfall_overload",
    }

    pass_flags = {
        "duration_gate": duration_days == 3,
        "eastern_annual_gate": eastern_annual_ratio >= 1.0,
        "airport_annual_gate": airport_annual_ratio >= 0.5,
        "airport_grid_contrast_gate": airport_to_grid_ratio >= 5.0,
        "eastern_grid_contrast_gate": eastern_to_grid_ratio >= 10.0,
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "final_json_and_label",
                "points": 3,
                "description": "Returns the requested compact JSON fields and the annual_scale_short_duration_rainfall_overload label.",
                "partial_credit": "Give 1-2 points for a near-complete JSON object with a semantically equivalent label but missing or renamed fields.",
            },
            {
                "name": "duration_and_annual_midpoint",
                "points": 3,
                "description": "Computes the inclusive 3-day event window and the 170.0 mm annual rainfall midpoint.",
                "partial_credit": "Give 1-2 points for only one correct value or a minor inclusive-date error.",
            },
            {
                "name": "annual_normalized_ratios",
                "points": 4,
                "description": "Computes eastern_annual_ratio = 1.47 and airport_annual_ratio = 0.70 with formulas.",
                "partial_credit": "Give 1-3 points for one correct ratio, swapped numerator context, or small rounding mistakes.",
            },
            {
                "name": "airport_typical_annual",
                "points": 3,
                "description": "Computes the implied Dubai airport typical annual rainfall as 119.0 / 1.5 = 79.3 mm.",
                "partial_credit": "Give 1-2 points for identifying the multiplier but misrounding or omitting units.",
            },
            {
                "name": "gridded_max_and_contrast",
                "points": 3,
                "description": "Identifies 18.637 mm as the largest gridded event maximum and computes airport/eastern report-to-grid ratios of 6.39 and 13.41.",
                "partial_credit": "Give 1-2 points for using the right maximum with one ratio error or choosing a lower gridded product by mistake.",
            },
            {
                "name": "threshold_logic",
                "points": 3,
                "description": "Shows that all five duration, annual-ratio, and report-to-grid pass conditions are satisfied.",
                "partial_credit": "Give 1-2 points for the correct final pass state with incomplete or partially wrong inequality checks.",
            },
            {
                "name": "concise_computed_interpretation",
                "points": 1,
                "description": "Keeps the interpretation as a short rainfall-load conclusion and avoids extra impact totals not derived from the requested calculations.",
                "partial_credit": "No credit if the answer expands into broad incident narrative.",
            },
        ],
    }

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": "CSX-058",
        "task_type": "short_answer",
        "target_family": "formula_derivation_consistency_proof",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "tolerances": {
            "duration_days": 0,
            "annual_midpoint_mm": 0.1,
            "rainfall_ratio": 0.02,
            "airport_typical_annual_mm": 0.2,
            "max_gridded_precip_mm": 0.001,
            "report_to_grid_ratio": 0.03,
        },
        "decision_rule": {
            "label_when_all_pass": primary_gt["final_label"],
            "pass_flags": pass_flags,
            "thresholds": {
                "duration_days": 3,
                "eastern_annual_ratio_min": 1.0,
                "airport_annual_ratio_min": 0.5,
                "airport_to_grid_ratio_min": 5.0,
                "eastern_to_grid_ratio_min": 10.0,
            },
        },
        "key_values": {
            "event_name": event["event_name"],
            "event_window": f"{start} to {end}",
            "report_rainfall_mm": {
                "eastern_uae_less_than_24h": eastern_mm,
                "dubai_airport_daily": airport_mm,
            },
            "annual_rainfall_range_mm": [
                report_amounts["uae_annual_low_mm"],
                report_amounts["uae_annual_high_mm"],
            ],
            "gridded_precip_maxima_mm": gridded_precip,
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_003_Locked_event_anchor_April_2024_UAE_and_Dubai_record_rainfall_flood.json",
                "data/event_reports/event_reports_004_01_Locked_package_evidence_report.html.html",
                "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
                "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
                "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
            ],
        },
    }

    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(result, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
